// packages/storybook/.storybook/preview.ts
import type { Preview } from '@storybook/html';

// 👇 Import tokens and component styles
import '../../css/src/index.css';
// 👇 The default theme's fonts, when it stores any (generated by build:themes)
import '../../css/src/fonts.css';
// 👇 Every other theme's stylesheet, applied by the Theme toolbar (generated by build:themes)
import themeConfig from '../../../tokens/themes.json';

const byName = <T,>(files: Record<string, unknown>, ext: number) => Object.fromEntries(Object.entries(files).map(([path, v]) => [path.split('/').pop()!.slice(0, -ext), v as T]));
const THEMES = byName<string>(import.meta.glob('../../css/src/themes/*.css', { query: '?inline', import: 'default', eager: true }), 4);
/* A sub-brand ("extends") needs its parents' stylesheets first, and its class */
const PARENT = Object.fromEntries(
  Object.entries(byName<{ extends?: string }>(import.meta.glob('../../../tokens/themes/*.json', { eager: true, import: 'default' }), 5)).map(([name, t]) => [name, t.extends]),
);
const chainOf = (name: string): string[] => (PARENT[name] ? [...chainOf(PARENT[name]!), name] : [name]);
// 👇 Import Storybook demo harness utilities
import './demo.css';

const preview: Preview = {
  globalTypes: {
    brand: {
      name: 'Theme',
      description: 'The theme: the library default, a theme from tokens/themes, or a sub-brand (its class goes on <html>)',
      defaultValue: themeConfig.storybook ?? themeConfig.site,
      toolbar: {
        icon: 'paintbrush',
        items: [themeConfig.default, ...Object.keys(THEMES)].map((name) => ({
          value: name,
          title: `${name}${name === themeConfig.default ? ' (default)' : ''}${name === themeConfig.site ? ' (site)' : ''}${PARENT[name] ? ` (sub-brand of ${PARENT[name]})` : ''}`,
        })),
        dynamicTitle: true,
      },
    },
    theme: {
      name: 'Color Scheme',
      description: 'Global color scheme for components (native light-dark)',
      defaultValue: 'auto',
      toolbar: {
        icon: 'circlehollow',
        items: [
          { value: 'auto', icon: 'browser', title: 'System (Auto)' },
          { value: 'light', icon: 'sun', title: 'Light Mode' },
          { value: 'dark', icon: 'moon', title: 'Dark Mode' },
        ],
        dynamicTitle: true,
      },
    },
  },
  decorators: [
    (story, context) => {
      const theme = context.globals.theme || 'auto';
      const root = document.documentElement;

      /* The theme's stylesheet goes after the library's; the default has none */
      const brand = context.globals.brand ?? themeConfig.site;
      let sheet = document.getElementById('sb-theme');
      if (!sheet) {
        sheet = Object.assign(document.createElement('style'), { id: 'sb-theme' });
        document.head.append(sheet);
      }
      const chain = chainOf(brand);
      sheet.textContent = chain.map((name) => THEMES[name] ?? '').join('\n');
      root.classList.forEach((c) => c.startsWith('theme-') && root.classList.remove(c));
      chain.filter((name) => PARENT[name]).forEach((name) => root.classList.add(`theme-${name}`));

      if (theme === 'dark') {
        root.style.colorScheme = 'dark';
      } else if (theme === 'light') {
        root.style.colorScheme = 'light';
      } else {
        root.style.colorScheme = 'light dark';
      }

      return story();
    },
  ],
  parameters: {
    backgrounds: {
      disable: true,
    },
    options: {
      storySort: {
        method: 'alphabetical',
        order: ['Tokens', 'Atoms', 'Molecules', 'Organisms', 'Layout', 'Utilities', 'Recipes', '*'],
        locales: 'en-US',
      },
    },
    actions: { argTypesRegex: '^on[A-Z].*' },
    controls: {
      matchers: {
        color: /(background|color)$/i,
        date: /Date$/i,
      },
    },
    // 👇 Global Accessibility Settings
    a11y: {
      // Optional: Set test behavior ('error', 'todo', or 'off') if using Storybook's test runner
      test: 'error', 
      config: {
        rules: [
          {
            id: 'color-contrast',
            enabled: true,
          },
          // Standards decide, not the tool: an <aside> in <main> is valid HTML
          // and ARIA; only axe's best-practice rule objects
          {
            id: 'landmark-complementary-is-top-level',
            enabled: false,
          },
          // A Divider in a list is <li role="separator">: HTML (a list holds
          // <li>s) and ARIA in HTML (separator is allowed on <li>) permit it;
          // axe's list rule wants every child to stay a list item
          {
            id: 'list',
            enabled: false,
          },
        ],
      },
    },
  },
};

export default preview;